import{_ as e,o as t,c as r,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"2020-01-20 :: Ceph Orchestration Meeting","description":"","frontmatter":{"title":"2020-01-20 :: Ceph Orchestration Meeting","date":"2020-01-20T00:00:00.000Z","updated":"2020-01-24T00:00:00.000Z","tags":["Ceph","Orchestration","Storage","Distributed Storage","CephFS"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/2020-01-20_-_-_Ceph_Orchestration_Meeting.md","filePath":"posts/2020/2020-01-20_-_-_Ceph_Orchestration_Meeting.md","lastUpdated":1780460162000}'),l={name:"posts/2020/2020-01-20_-_-_Ceph_Orchestration_Meeting.md"};function o(n,a,s,h,d,c){return t(),r("div",null,[...a[0]||(a[0]=[i('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="参会人员" tabindex="-1">参会人员 <a class="header-anchor" href="#参会人员" aria-label="Permalink to &quot;参会人员&quot;">​</a></h4><ul><li>会议参与者包括Farrakhan及其他相关人员。</li></ul><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>Orchestrator项目讨论</strong></p><ul><li>决定停用现有的trailer bots（ferry和trailer Borden的orchestrated robot），转而支持Redman项目中的新Orchestrator。</li><li>新Orchestrator项目提供更多功能，如适当的过滤等。</li></ul></li><li><p><strong>培训进展分享</strong></p><ul><li>讨论了培训的进展，目前主要支持draining功能，未来可能扩展到其他功能。</li></ul></li><li><p><strong>技术问题讨论</strong></p><ul><li>讨论了关于dead list设置的问题，涉及到设备名称的使用和错误报告的改进。</li><li>讨论了SSH连接问题，特别是remoter库的使用和可能的替代方案。</li></ul></li><li><p><strong>SEF ATM安装和升级</strong></p><ul><li>讨论了SEF ATM的安装方式，包括使用pip安装和可能的替代方案。</li><li>讨论了SEF ATM在不同操作系统上的安装和维护问题。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>停用现有的trailer bots，转而支持新Orchestrator项目。</li><li>继续推进SEF ATM的pip安装方式，并考虑其在不同操作系统上的兼容性问题。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>继续改进Orchestrator项目，确保其功能和稳定性。</li><li>完善SEF ATM的安装和升级流程，特别是pip安装方式的优化。</li><li>继续解决技术问题，如SSH连接问题和错误报告的改进。</li></ul><h4 id="其他讨论" tabindex="-1">其他讨论 <a class="header-anchor" href="#其他讨论" aria-label="Permalink to &quot;其他讨论&quot;">​</a></h4><ul><li>讨论了SEF ATM在不同操作系统上的安装和维护问题，特别是Debian系统的支持。</li><li>讨论了SEF ATM的版本控制和同步问题，确保用户能够获取正确的版本。</li></ul><h4 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h4><ul><li>会议在讨论完所有议题后结束，感谢所有参与者的贡献。</li></ul><h4 id="改进点" tabindex="-1">改进点 <a class="header-anchor" href="#改进点" aria-label="Permalink to &quot;改进点&quot;">​</a></h4><ul><li>纠正了原总结中关于“Orchestrator项目具有更多功能，如适当的过滤等”这一点的描述，因为在原始字幕中没有具体说明“适当的过滤”指的是什么。</li><li>在技术问题讨论中增加了关于SSH连接问题的详细信息，包括remoter库的使用和可能的替代方案。</li><li>在SEF ATM安装和升级部分，增加了关于pip安装方式和不同操作系统兼容性问题的讨论。</li></ul>',15)])])}const p=e(l,[["render",o]]);export{_ as __pageData,p as default};
